    let modoAdmin = false;
    const msgEl = document.getElementById("msg");
    function mostrarMsg(texto, tipo) {
      msgEl.textContent = texto;
      msgEl.className = "msg " + tipo;
      setTimeout(() => { msgEl.className = "msg"; }, 4000);
    }
    document.getElementById("tab-login").onclick = () => {
      document.getElementById("tab-login").classList.add("ativo");
      document.getElementById("tab-cadastro").classList.remove("ativo");
      document.getElementById("form-login").style.display = "";
      document.getElementById("form-cadastro").style.display = "none";
    };
    document.getElementById("tab-cadastro").onclick = () => {
      document.getElementById("tab-cadastro").classList.add("ativo");
      document.getElementById("tab-login").classList.remove("ativo");
      document.getElementById("form-cadastro").style.display = "";
      document.getElementById("form-login").style.display = "none";
    };
    document.getElementById("toggle-admin").onclick = () => {
      if (modoAdmin) {
        document.getElementById("login-usuario").value = "";
        document.getElementById("login-senha").value = "";
        document.getElementById("login-usuario").placeholder = "seu-usuario";
        document.getElementById("toggle-admin").textContent = "Sou administrador";
        modoAdmin = false;
      } else {
        document.getElementById("login-usuario").placeholder = "admin";
        document.getElementById("login-senha").focus();
        document.getElementById("toggle-admin").textContent = "Sou usuário comum";
        modoAdmin = true;
      }
      document.getElementById("tab-login").click();
    };
    document.getElementById("form-login").onsubmit = async (e) => {
      e.preventDefault();
      const btn = document.getElementById("btn-login");
      btn.disabled = true; btn.textContent = "Entrando...";
      try {
        const r = await fetch("/api/login", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            usuario: document.getElementById("login-usuario").value,
            senha: document.getElementById("login-senha").value
          })
        });
        const d = await r.json();
        if (d.erro) { mostrarMsg(d.erro, "erro"); return; }
        window.location.href = "/";
      } catch { mostrarMsg("Erro de conexão.", "erro"); }
      btn.disabled = false; btn.textContent = "Entrar";
    };
    document.getElementById("form-cadastro").onsubmit = async (e) => {
      e.preventDefault();
      const btn = document.getElementById("btn-cadastro");
      btn.disabled = true; btn.textContent = "Criando...";
