        if (d.erro) { mostrarMsg(d.erro, "erro"); return; }
        window.location.href = "/";
      } catch { mostrarMsg("Erro de conexão.", "erro"); }
      btn.disabled = false; btn.textContent = "Criar minha conta";
    };
  </script>
