    let todasDespesas = [];
    let todasCategorias = [];
    const BRL = (v) => "R$ " + (v || 0).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    function toast(msg, tipo) {
      const el = document.getElementById("toast");
      el.textContent = msg;
      el.className = "toast " + tipo;
      setTimeout(() => { el.className = "toast"; }, 2500);
    }

    function mesNome(km) {
      const [ano, mes] = km.split("-").map(Number);
      const nomes = ["janeiro","fevereiro","março","abril","maio","junho","julho","agosto","setembro","outubro","novembro","dezembro"];
      return nomes[mes - 1] + " de " + ano;
    }

    async function carregar() {
      const [rResumo, rDesp, rCats] = await Promise.all([
        fetch("/api/meu-resumo").then(r => r.json()),
        fetch("/api/minhas-despesas").then(r => r.json()),
        fetch("/api/categorias").then(r => r.json())
      ]);
      document.getElementById("res-total").textContent = BRL(rResumo.totalGeral);
      document.getElementById("res-mes").textContent = BRL(rResumo.totalMesAtual);
      document.getElementById("res-qtd").textContent = rResumo.qtd;
      const agora = new Date();
      document.getElementById("mes-nome").textContent = mesNome(agora.getFullYear() + "-" + String(agora.getMonth() + 1).padStart(2, "0"));
      todasDespesas = rDesp.despesas;
      todasCategorias = rCats.categorias.filter(c => c.ativa);
      preencherCategorias();
      preencherFiltroMes();
      render();
    }

    function preencherCategorias() {
      const sel = document.getElementById("novo-cat");
      sel.innerHTML = '<option value="">Sem categoria</option>';
      todasCategorias.forEach(c => {
        sel.innerHTML += `<option value="${c.id}">${c.nome}</option>`;
      });
      const filt = document.getElementById("filtro-cat");
      const atual = filt.value;
      filt.innerHTML = '<option value="">Todas as categorias</option>';
      todasCategorias.forEach(c => {
        filt.innerHTML += `<option value="${c.id}">${c.nome}</option>`;
      });
      filt.value = atual;
    }

    function preencherFiltroMes() {
      const meses = {};
      todasDespesas.forEach(d => {
        const [ano, mes] = d.data.slice(0, 7).split("-").map(Number);
        const km = d.data.slice(0, 7);
        if (!meses[km]) meses[km] = mesNome(km);
      });
      const sel = document.getElementById("filtro-mes");
      const atual = sel.value;
      sel.innerHTML = '<option value="">Todos os meses</option>';
      Object.keys(meses).sort().reverse().forEach(km => {
        sel.innerHTML += `<option value="${km}">${meses[km]}</option>`;
      });
      sel.value = atual;
    }

    function render() {
      const fc = document.getElementById("filtro-cat").value;
      const fm = document.getElementById("filtro-mes").value;
      const lista = todasDespesas.filter(d => {
        if (fc && d.categoriaId !== fc) return false;
        if (fm && d.data.slice(0, 7) !== fm) return false;
        return true;
      });
      const tbody = document.getElementById("tbody");
      const vazio = document.getElementById("vazio");
      if (lista.length === 0) { tbody.innerHTML = ""; vazio.style.display = ""; return; }
      vazio.style.display = "none";
      tbody.innerHTML = lista.map(d => {
        const cor = d.categoria ? (d.categoria.cor || "#64748b") : "#64748b";
        const nomeCat = d.categoria ? d.categoria.nome : "Sem categoria";
        return `<tr>
          <td>${d.dataBR}</td>
          <td>${d.descricao.replace(/</g, "&lt;")}</td>
          <td><span class="badge-cat" style="background:${cor}33;color:${cor};border:1px solid ${cor}55">${nomeCat}</span></td>
          <td style="text-align:right;font-weight:600">${BRL(d.valor)}</td>
          <td style="text-align:right"><button class="btn-del" data-id="${d.id}" title="Apagar">🗑️</button></td>
        </tr>`;
      }).join("");
      tbody.querySelectorAll(".btn-del").forEach(b => {
        b.onclick = async () => {
          if (!confirm("Apagar este gasto?")) return;
          const r = await fetch("/api/despesas/" + b.dataset.id, { method: "DELETE" });
          const d = await r.json();
          if (d.erro) return toast(d.erro, "erro");
          toast("Gasto apagado.", "ok");
          carregar();
        };
      });
    }

    document.getElementById("filtro-cat").onchange = render;
    document.getElementById("filtro-mes").onchange = render;

    document.getElementById("btn-add").onclick = async () => {
      const desc = document.getElementById("novo-desc").value.trim();
      const valor = document.getElementById("novo-valor").value;
      const data = document.getElementById("novo-data").value;
      const cat = document.getElementById("novo-cat").value;
      if (!desc) return toast("Descreva o gasto.", "erro");
      if (!valor || parseFloat(valor) <= 0) return toast("Informe um valor válido.", "erro");
      const r = await fetch("/api/despesas", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ descricao: desc, valor: parseFloat(valor), data: data || null, categoriaId: cat || null })
      });
      const d = await r.json();
      if (d.erro) return toast(d.erro, "erro");
      toast("Gasto adicionado! ✅", "ok");
      document.getElementById("novo-desc").value = "";
      document.getElementById("novo-valor").value = "";
      carregar();
    };

    document.getElementById("btn-sair").onclick = async () => {
      await fetch("/api/logout", { method: "POST" });
      window.location.href = "/";
    };

    document.getElementById("btn-senha").onclick = () => document.getElementById("modal-senha").classList.add("aberto");
    document.getElementById("btn-cancelar-senha").onclick = () => document.getElementById("modal-senha").classList.remove("aberto");
    document.getElementById("btn-salvar-senha").onclick = async () => {
      const r = await fetch("/api/senha", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ senhaAtual: document.getElementById("senha-atual").value, senhaNova: document.getElementById("senha-nova").value })
      });
      const d = await r.json();
      if (d.erro) return toast(d.erro, "erro");
      toast("Senha alterada! ✅", "ok");
      document.getElementById("modal-senha").classList.remove("aberto");
      document.getElementById("senha-atual").value = "";
      document.getElementById("senha-nova").value = "";
    };

    document.getElementById("novo-data").value = new Date().toISOString().slice(0, 10);
    fetch("/api/status").then(r => r.json()).then(d => {
      if (d.nome) document.getElementById("user-name").textContent = d.nome;
    });
    carregar();
  </script>
</body>
</html>

